NEW_FILES = {'tests/test_parche117.py': '"""parche-117: preguntas sobre lo aprendido de textos, traza de lectura y adjetivos con lema verbal."""\nimport os\nimport tempfile\n\nfrom src.language.dialogue import Conversation\nfrom src.language.lector_ud import LectorUD, escribir_traza\nfrom src.language.qa import QA\nfrom src.memory.store import MemoryStore\nfrom src.reasoning.lessons import deduce_all\n\n\ndef _conv():\n    m = MemoryStore(os.path.join(tempfile.mkdtemp(), "m.json"))\n    m.add_fact(("AKIRA_TORIYAMA", "CREAR", "GOKU"), when="1984")\n    m.add_fact(("GOKU", "EXHIBIR", "COLA_DE_MONO"))\n    m.add_fact(("LEON", "COMER", "CARNE"))\n    m.add_fact(("ANA", "ESCRIBIR", "POEMA"))\n    return Conversation(m, None, lambda mm, p: QA(mm, (lambda *a: []), lambda f: deduce_all(f, mm.active_lessons())))\n\n\ndef test_preguntas_sobre_lo_leido():\n    c = _conv()\n    for q in ("quien creo a Goku?", "quien es el creador de Gokū?", "Quien fue el creador de goku?"):\n        assert "Toriyama" in c.say(q), q\n    assert "Cola" in c.say("que exhibe Goku?")\n    assert "Carne" in c.say("que come el leon?")\n    assert "Poema" in c.say("quien escribe poemas?")\n    assert "Toriyama" not in c.say("quien escribio el poema?")\n\n\ndef test_sin_dato_sigue_diciendo_que_no_sabe():\n    c = _conv()\n    assert "Toriyama" not in c.say("quien dibujo a Goku?")\n\n\nclass _P:\n    def tree(self, s):\n        return [("Goku", "PROPN", 3, "nsubj", "Goku"), ("fue", "AUX", 3, "cop", "ser"), ("vencido", "ADJ", 0, "root", "vencer"), (".", "PUNCT", 3, "punct", ".")]\n\n\ndef test_adjetivo_con_lema_verbal_y_traza():\n    m = MemoryStore(os.path.join(tempfile.mkdtemp(), "m.json"))\n    rep = LectorUD(m, _P()).leer("Goku fue vencido por alguien conocido.")\n    claves = {(h["s"], h["p"], h["o"]) for h in rep["hechos"]}\n    assert ("GOKU", "SER", "VENCIDO") in claves and not any(o == "VENCER" for _, _, o in claves)\n    ruta = os.path.join(tempfile.mkdtemp(), "r", "l.txt")\n    escribir_traza(rep, ruta)\n    assert "GOKU SER VENCIDO" in open(ruta, encoding="utf-8").read()\n', 'src/language/lectura_qa.py': '"""parche-117: preguntas sobre lo aprendido leyendo textos ("quien creo a X", "quien fue el creador de X", "que exhibe X", "que come el leon").\nSe usa solo cuando la comprension normal no contesta. Sin listas de dominio: la forma verbal se enlaza con los predicados que hay en memoria\npor su raiz y su terminacion, y los nombres de agente (creador, descubridor, escritor...) con el verbo del que salen."""\nfrom __future__ import annotations\n\nimport re\nfrom typing import List, Optional\n\nfrom .irregulares import IRREG\nfrom .lexicon import norm\n\n_ART = r"(?:el|la|los|las|un|una|al|del)"\n_FIN = {"ar": ["o", "as", "a", "amos", "an", "e", "es", "en", "aba", "abas", "aban", "o", "aste", "amos", "aron", "ando", "ado", "ada", "ados", "adas", "are", "ara"],\n        "er": ["o", "es", "e", "emos", "en", "ia", "ias", "ian", "i", "iste", "io", "imos", "ieron", "iendo", "ido", "ida", "idos", "idas", "a", "an"],\n        "ir": ["o", "es", "e", "imos", "en", "ia", "ias", "ian", "i", "iste", "io", "ieron", "iendo", "ido", "ida", "idos", "idas", "a", "an"]}\n\n\ndef _predicados(qa) -> List[str]:\n    return sorted({f["p"] for f in qa.m.facts if not f.get("neg")})\n\n\ndef _verbos(qa, forma: str) -> List[str]:\n    """Predicados de la memoria que pueden ser la forma conjugada dada."""\n    f = norm(forma)\n    out = []\n    irr = IRREG.get(f) or IRREG.get(forma.lower())\n    for p in _predicados(qa):\n        base = p.lower().split("_")[0]\n        if len(base) < 4 or base[-2:] not in _FIN:\n            continue\n        if irr and norm(irr) == norm(base):\n            out.append(p)\n            continue\n        st = base[:-2]\n        for stem in {st, st[:-1] + {"c": "qu", "g": "gu", "z": "c"}.get(st[-1:], st[-1:])}:\n            if f.startswith(stem) and f[len(stem):] in _FIN[base[-2:]] + [""]:\n                out.append(p)\n                break\n    return out\n\n\ndef _verbo_de_agente(qa, nombre: str) -> List[str]:\n    """creador -> crear, descubridor -> descubrir, escritor -> escribir, fundador -> fundar."""\n    n = norm(nombre)\n    m = re.fullmatch(r"(.{3,}?)(?:ad|ed|id)?(?:or|ora|ores|oras)", n)\n    if not m:\n        return []\n    raiz = m.group(1)\n    res = []\n    for p in _predicados(qa):\n        base = norm(p.lower().split("_")[0])\n        if base[-2:] in _FIN and (base[:-2].startswith(raiz[:max(3, len(raiz) - 1)]) or raiz.startswith(base[:-2][:max(3, len(base) - 3)])):\n            res.append(p)\n    return res\n\n\ndef _entidad(qa, texto: str) -> Optional[str]:\n    t = re.sub(r"^" + _ART + r"\\s+", "", texto.strip(), flags=re.I)\n    clave = re.sub(r"\\s+", "_", norm(t)).upper()\n    if not clave:\n        return None\n    for k in (clave, clave + "S", clave[:-1] if clave.endswith("S") else clave, clave[:-2] if clave.endswith("ES") else clave):\n        if any(f["s"] == k or f["o"] == k for f in qa.m.facts):\n            return k\n    al = getattr(qa.m, "alias", {}).get(clave)\n    return al or None\n\n\ndef responder(qa, pregunta: str) -> Optional[str]:\n    q = re.sub(r"[¿?¡!]", " ", pregunta).strip()\n    q = re.sub(r"\\s+", " ", q)\n    low = q.lower()\n    hits = []\n    m = re.fullmatch(r"(?:y )?(quien|quienes|quién)\\s+(?:fue|es|era|son|fueron)\\s+" + _ART + r"\\s+(\\w+(?:dor|dora|tor|tora|dores|tores))\\s+(?:de|del)\\s+(.+)", low)\n    if m:\n        ent = _entidad(qa, m.group(3))\n        for p in _verbo_de_agente(qa, m.group(2)):\n            if ent:\n                hits += qa.lookup(None, p, ent)\n    if not hits:\n        m = re.fullmatch(r"(?:y )?(?:quien|quienes|quién)\\s+(\\w+)\\s+(?:a la |a los |a las |al |a |el |la |los |las )?(.+)", low)\n        if m:\n            ent = _entidad(qa, m.group(2))\n            for p in (_verbos(qa, m.group(1)) if ent else []):\n                hits += qa.lookup(None, p, ent)\n    if not hits:\n        m = re.fullmatch(r"(?:y )?(?:qu[eé]|a qu[eé]|con qu[eé])\\s+(\\w+)\\s+(.+)", low)\n        if m:\n            ent = _entidad(qa, m.group(2))\n            for p in (_verbos(qa, m.group(1)) if ent else []):\n                hits += qa.lookup(ent, p, None)\n    hits = list(dict.fromkeys(hits))\n    if not hits:\n        return None\n    return " ".join(dict.fromkeys(qa.say(f) + "." for f in hits))[:600]\n'}
SOFT = []

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")


    for rel, marca, bloque, antes in SOFT:                              # documentacion: tolerante, nunca bloquea
        p = root / rel
        try:
            t = p.read_text(encoding="utf-8") if p.exists() else ""
            if marca in t:
                continue
            if antes and antes in t:
                t = t.replace(antes, bloque + antes, 1)
            else:
                t = t + ("" if t.endswith("\n") or not t else "\n") + bloque
            if p.exists():
                (bk / rel).parent.mkdir(parents=True, exist_ok=True); shutil.copy2(p, bk / rel)
            p.write_text(t, encoding="utf-8"); print(f"  actualizado {rel}")
        except Exception as e:
            print(f"  (aviso) no se pudo actualizar {rel}: {e!r}")
    print(f"parche-117 instalado. Copias en {bk}" if plan else "parche-117: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

